import{_ as o,o as e,c as r,a2 as a}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Feishu (Lark)","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/channels/feishu.md","filePath":"ja/integrations/channels/feishu.md","lastUpdated":1792323081000}'),s={name:"ja/integrations/channels/feishu.md"};function i(n,t,h,l,d,g){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="feishu-lark" tabindex="-1">Feishu (Lark) <a class="header-anchor" href="#feishu-lark" aria-label="Permalink to &quot;Feishu (Lark)&quot;">​</a></h1><p>Feishu オープンプラットフォーム経由で接続し、企業の Bot がグループチャットとプライベートチャットでユーザーとやり取りできるようにします。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li><a href="https://open.feishu.cn/app" target="_blank" rel="noreferrer">Feishu オープンプラットフォーム</a> にログインでき、カスタムアプリを作成できるアカウント。</li><li>Memoh Bot。チャネルはその <strong>プラットフォーム</strong> タブで設定します。</li></ul><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><h3 id="_1-feishu-オープンプラットフォームでカスタムアプリを作成する" tabindex="-1">1. Feishu オープンプラットフォームでカスタムアプリを作成する <a class="header-anchor" href="#_1-feishu-オープンプラットフォームでカスタムアプリを作成する" aria-label="Permalink to &quot;1. Feishu オープンプラットフォームでカスタムアプリを作成する&quot;">​</a></h3><ol><li><a href="https://open.feishu.cn/app" target="_blank" rel="noreferrer">Feishu オープンプラットフォーム</a> を開いてログインします。</li><li><strong>カスタムアプリを作成</strong> をクリックし、名前と説明を入力して作成します。</li><li>左側のメニューから <strong>認証情報と基本情報</strong> に移動します。</li><li><strong>App ID</strong> と <strong>App Secret</strong> をコピーします。</li></ol><h3 id="_2-feishu-オープンプラットフォームで-bot-機能を有効にする" tabindex="-1">2. Feishu オープンプラットフォームで Bot 機能を有効にする <a class="header-anchor" href="#_2-feishu-オープンプラットフォームで-bot-機能を有効にする" aria-label="Permalink to &quot;2. Feishu オープンプラットフォームで Bot 機能を有効にする&quot;">​</a></h3><p><strong>アプリ機能</strong> → <strong>Bot</strong> に移動し、有効化します。</p><h3 id="_3-feishu-オープンプラットフォームで権限を設定する" tabindex="-1">3. Feishu オープンプラットフォームで権限を設定する <a class="header-anchor" href="#_3-feishu-オープンプラットフォームで権限を設定する" aria-label="Permalink to &quot;3. Feishu オープンプラットフォームで権限を設定する&quot;">​</a></h3><ol><li><strong>アプリ機能</strong> → <strong>権限管理</strong> に移動します。</li><li>少なくとも次を有効にします。 <ul><li><code>im:message</code>（メッセージの送受信）</li><li><code>im:chat</code>（グループ情報など）</li></ul></li><li>組織で必要とされる場合は、<strong>権限を申請</strong> をクリックして提出します。</li></ol><h3 id="_4-memoh-で-feishu-チャネルを追加する-デフォルト-長期接続" tabindex="-1">4. Memoh で Feishu チャネルを追加する（デフォルト：長期接続） <a class="header-anchor" href="#_4-memoh-で-feishu-チャネルを追加する-デフォルト-長期接続" aria-label="Permalink to &quot;4. Memoh で Feishu チャネルを追加する（デフォルト：長期接続）&quot;">​</a></h3><ol><li>Bot の <strong>プラットフォーム</strong> タブを開き、<strong>Feishu</strong> チャネルを追加します。</li><li><strong>受信方式</strong> はデフォルトの <code>websocket</code> のままにします。</li><li><strong>App ID</strong> と <strong>App Secret</strong> を入力します。国際版 Lark を使う場合は <strong>リージョン</strong> を <code>lark</code> に切り替えます。</li><li><strong>Save</strong> をクリックします。メッセージは Feishu の <strong>WebSocket 長期接続</strong> 経由で届くため、公開のコールバック URL は不要で、イベントサブスクリプションの設定も要りません。</li></ol><h3 id="_5-オプション-webhook-受信に切り替える" tabindex="-1">5. オプション：Webhook 受信に切り替える <a class="header-anchor" href="#_5-オプション-webhook-受信に切り替える" aria-label="Permalink to &quot;5. オプション：Webhook 受信に切り替える&quot;">​</a></h3><p>サーバーがインターネットから到達可能で、イベントコールバック方式を使いたい場合にのみ選択してください。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>このステップでは Memoh と Feishu コンソールを行き来します。Memoh が生成したコールバック URL を <strong>イベントサブスクリプション</strong> ページに貼り付けるので、Feishu コンソールはまだ閉じないでください。</p></div><ol><li>Memoh で <strong>受信方式</strong> を <code>webhook</code> に変更します。<strong>App ID</strong>、<strong>App Secret</strong> に加えて、Feishu コンソールのイベントサブスクリプション設定と一致する <strong>Encrypt Key</strong> と <strong>Verification Token</strong> も入力します。</li><li><strong>Save</strong> をクリックすると、画面に <strong>Webhook コールバック URL</strong> が生成されるので、コピーします。</li><li>Feishu コンソールに戻り、<strong>アプリ設定</strong> → <strong>イベントサブスクリプション</strong> を開き、URL を <strong>リクエスト URL</strong> に貼り付けて保存します。</li><li><strong>メッセージ受信</strong>（<code>im.message.receive_v1</code>）などのイベントを追加します。</li></ol><blockquote><p>公式ガイド：<a href="https://open.feishu.cn/document/client-docs/bot-v3/add-custom-bot" target="_blank" rel="noreferrer">Feishu カスタム Bot</a></p></blockquote><h3 id="_6-feishu-オープンプラットフォームでアプリをリリースする" tabindex="-1">6. Feishu オープンプラットフォームでアプリをリリースする <a class="header-anchor" href="#_6-feishu-オープンプラットフォームでアプリをリリースする" aria-label="Permalink to &quot;6. Feishu オープンプラットフォームでアプリをリリースする&quot;">​</a></h3><ol><li><strong>アプリリリース</strong> → <strong>バージョン管理とリリース</strong> に移動します。</li><li><strong>バージョンを作成</strong> をクリックし、情報を記入して承認を申請します。</li><li>承認されて公開されると、テナント内で Bot が利用できるようになります。</li></ol><h2 id="認証情報" tabindex="-1">認証情報 <a class="header-anchor" href="#認証情報" aria-label="Permalink to &quot;認証情報&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td><strong>App ID</strong></td><td>Feishu オープンプラットフォームの <strong>認証情報と基本情報</strong> ページで取得します。</td></tr><tr><td><strong>App Secret</strong></td><td>App ID と同じページで取得します。</td></tr><tr><td><strong>リージョン</strong></td><td>国際版 Lark を使う場合は <code>lark</code> に切り替えます。</td></tr><tr><td><strong>受信方式</strong></td><td><code>websocket</code>（デフォルト、長期接続）または <code>webhook</code>。</td></tr><tr><td><strong>Encrypt Key</strong></td><td>webhook モードでのみ必要。Feishu コンソールのイベントサブスクリプション設定と一致させる必要があります。</td></tr><tr><td><strong>Verification Token</strong></td><td>webhook モードでのみ必要。Feishu コンソールのイベントサブスクリプション設定と一致させる必要があります。</td></tr></tbody></table><h2 id="動作確認" tabindex="-1">動作確認 <a class="header-anchor" href="#動作確認" aria-label="Permalink to &quot;動作確認&quot;">​</a></h2><p>Feishu で Bot とのプライベートチャットを開き、<code>/help</code> を送信します。Bot がコマンド一覧を返せば、チャネルは機能しています。</p><h2 id="グループチャット" tabindex="-1">グループチャット <a class="header-anchor" href="#グループチャット" aria-label="Permalink to &quot;グループチャット&quot;">​</a></h2><p>Feishu はグループチャットに対応しています。Bot をグループに追加して @メンションすると、グループ内で会話できます。</p><h2 id="無効化と認証情報の更新" tabindex="-1">無効化と認証情報の更新 <a class="header-anchor" href="#無効化と認証情報の更新" aria-label="Permalink to &quot;無効化と認証情報の更新&quot;">​</a></h2><p>Bot の <strong>プラットフォーム</strong> タブから、いつでもこのチャネルを無効化・削除できます。認証情報を更新するときは、該当するフィールド（<strong>App Secret</strong> など）を更新して保存してください。</p><h2 id="faq" tabindex="-1">よくある質問 <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;よくある質問 {#faq}&quot;">​</a></h2><h3 id="app-not-published" tabindex="-1">チャネルを設定したのに Bot が反応しない <a class="header-anchor" href="#app-not-published" aria-label="Permalink to &quot;チャネルを設定したのに Bot が反応しない {#app-not-published}&quot;">​</a></h3><p>カスタムアプリはまずリリースが必要です。Feishu オープンプラットフォームの <strong>アプリリリース</strong> → <strong>バージョン管理とリリース</strong> でバージョンを作成して承認を申請します。承認されて公開されると、テナント内で Bot が利用できるようになります。</p><h3 id="permission-approval" tabindex="-1">権限に承認が必要 <a class="header-anchor" href="#permission-approval" aria-label="Permalink to &quot;権限に承認が必要 {#permission-approval}&quot;">​</a></h3><p>組織によってはアプリ権限に承認フローがあります。<strong>アプリ機能</strong> → <strong>権限管理</strong> で <strong>権限を申請</strong> をクリックして提出してください。</p>',33)])])}const p=o(s,[["render",i]]);export{c as __pageData,p as default};
